using JTradeERP.Application.Common.Exceptions; using JTradeERP.Application.Common.Persistence; using JTradeERP.Application.Common.Security; using JTradeERP.Domain.Security; using MediatR; using Microsoft.Extensions.Options;
namespace JTradeERP.Application.Features.Security.RefreshAccessToken;
public sealed class RefreshAccessTokenHandler(IApplicationDbContext db,ITokenService tokens,IClock clock,IOptions<SecurityOptions> options,IRefreshTokenCookie cookie) : IRequestHandler<RefreshAccessTokenCommand,RefreshAccessTokenResponse>
{
 public async Task<RefreshAccessTokenResponse> Handle(RefreshAccessTokenCommand r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.RefreshToken))throw new AuthenticationFailureException("Refresh session is invalid.");var hash=tokens.HashOpaqueToken(r.RefreshToken);var old=db.RefreshTokens.SingleOrDefault(x=>x.TokenHash==hash);if(old is null)throw new AuthenticationFailureException("Refresh session is invalid.");var now=clock.UtcNow;if(!old.IsActive(now)){if(old.RevokedAt is not null){db.Add(new SecurityAuditEntry(null,"RefreshTokenReuseDetected","RefreshToken",old.Id.ToString(),null,"denied",Guid.NewGuid().ToString()));foreach(var token in db.RefreshTokens.Where(x=>x.FamilyId==old.FamilyId&&x.RevokedAt==null).ToArray())token.Revoke(now,"reuse-detected");await db.SaveChangesAsync(ct);}throw new AuthenticationFailureException("Refresh session is invalid.");}var u=db.Users.SingleOrDefault(x=>x.Id==old.UserId);if(u is null||!u.IsActive)throw new AuthenticationFailureException("Refresh session is invalid.");var roles=(from ur in db.UserRoles join role in db.Roles on ur.RoleId equals role.Id where ur.UserId==u.Id select role.Name).ToArray();var raw=tokens.CreateOpaqueToken();var expiry=now.AddDays(options.Value.RefreshTokenDays);var next=new RefreshToken(u.Id,tokens.HashOpaqueToken(raw),now,expiry,old.Id,old.FamilyId);db.Add(next);old.Revoke(now,"rotated",next.Id);var access=tokens.CreateAccessToken(u,roles);SecurityAuditWriter.Add(db,u.Id,"RefreshTokenRotated","RefreshToken",old.Id.ToString(),"active","rotated");await db.SaveChangesAsync(ct);cookie.Write(raw,expiry);return new(access.AccessToken,access.ExpiresAt);}
}
